var ErrorCodes = {
  Internal: "internal",
  Timeout: "timeout",
  InvalidInput: "invalid_input",
  NotFound: "not_found",
  SessionClosed: "session_closed",
  /** A human has taken over the session; agent actions are refused until hand-back. */
  SessionPaused: "session_paused",
  BrowserCrashed: "browser_crashed",
  /** Chromium did not start. `details.launch` says why and whether a retry can help. */
  BrowserLaunchFailed: "browser_launch_failed",
  /** The page's renderer crashed; the browser lives on. `navigate` or `reload` recovers the tab. */
  PageCrashed: "page_crashed",
  ProtocolError: "protocol_error",
  TargetDetached: "target_detached",
  NavigationBlocked: "navigation_blocked",
  ElementNotFound: "element_not_found",
  ElementNotVisible: "element_not_visible",
  ElementDisabled: "element_disabled",
  CapacityExceeded: "capacity_exceeded",
  /** The session's runner cannot be reached (gateway proxy). Retry briefly; if it persists, the session is lost. */
  RunnerUnavailable: "runner_unavailable",
  Unauthorized: "unauthorized",
  /** Authenticated, but the action is not permitted (terms not accepted, policy). */
  Forbidden: "forbidden",
  /** The resource exists in a state that conflicts with the request (an id already in use). */
  Conflict: "conflict",
  /** Installing or running a third-party skill needs an admin to accept what it asks for first. */
  ConsentRequired: "consent_required",
  /** The session's engine cannot do this (`details.engine`, `details.feature`). */
  UnsupportedOnEngine: "unsupported_on_engine",
  /** The API key belongs to another region. `details.region` names where to retry (D27: the api knows only its own URL, so no `host`). */
  WrongRegion: "wrong_region",
  /** Too many requests. `details.retryAfterS` says when to try again (also the `Retry-After` header). */
  RateLimited: "rate_limited",
  /** The Idempotency-Key was already used with a different request (method, path or body). */
  IdempotencyKeyReused: "idempotency_key_reused",
  /** The first request with this Idempotency-Key is still running; retry later. */
  IdempotencyInProgress: "idempotency_in_progress",
  /** The identity service (dashboard sign-in) cannot be reached; retry. */
  AuthUnavailable: "auth_unavailable",
  /** Sensitive action (key mint/revoke) needs a recent sign-in; sign in again and retry. */
  ReauthRequired: "reauth_required",
  /** The request body is larger than the endpoint accepts (`details.limitBytes`). */
  PayloadTooLarge: "payload_too_large",
  /** The route exists but not for this HTTP method; the `Allow` header lists the methods. */
  MethodNotAllowed: "method_not_allowed",
  /** The organisation is suspended by a platform admin; its keys and sign-ins are refused (hub D57). */
  OrgSuspended: "org_suspended",
  /** A write during a read-only impersonation by a platform admin (hub D57). */
  ImpersonationReadOnly: "impersonation_read_only",
  /** A platform admin cannot be impersonated (hub D57). */
  ImpersonationTargetAdmin: "impersonation_target_admin"
};
